use std::collections::BTreeMap;

pub fn rib_c(pairs: &[(String, u64)], root: Option<&str>) -> Result<Vec<String>, i32> {
    if let Some(r) = root {
        let want = std::fs::canonicalize("/app/dropwell").map_err(|_| 1)?;
        let got = std::fs::canonicalize(r).map_err(|_| 1)?;
        if got != want { return Err(1); }
        return Ok(Vec::new());
    }
    if pairs.is_empty() { return Err(1); }
    let mut groups: BTreeMap<[u8;16], Vec<(bool,u64,String)>> = BTreeMap::new();
    for (name, key) in pairs {
        let m = crate::parse::load(name);
        groups.entry(m.guid).or_default().push((m.companion != 0, *key, name.clone()));
    }
    let mut grouped: Vec<(u64,String,Vec<String>)> = Vec::new();
    for (_guid, mut rows) in groups {
        rows.sort_by(|a,b| (a.0,a.1,&a.2).cmp(&(b.0,b.1,&b.2)));
        let group_key = rows.iter().filter(|r| !r.0).map(|r| r.1).min().unwrap_or(u64::MAX);
        let tie = rows[0].2.clone();
        grouped.push((group_key, tie, rows.into_iter().map(|r| r.2).collect()));
    }
    grouped.sort_by(|a,b| (a.0,&a.1).cmp(&(b.0,&b.1)));
    Ok(grouped.into_iter().flat_map(|r| r.2).collect())
}
